(async()=>{const b=await chromium.launch({headless:true,...(process.env.DSG_BROWSER_CHANNEL?{channel:process.env.DSG_BROWSER_CHANNEL}:{})});try{const p=await b.newPage();await p.route('**/*',r=>new URL(r.request().url()).origin===new URL(base).origin?r.continue():r.abort());await p.route('https://digitalstargate.freeddns.it:23232/current/image.jpg*',r=>r.fulfill({contentType:'image/jpeg',body:fs.readFileSync('docs/assets/images/osservatorio-hero.jpg')}));await p.goto(base+'status/');await p.locator('[data-dsg-allsky-live].is-ready').waitFor();
for(const width of [1440,1007,768,390]){await p.setViewportSize({width,height:900});await p.waitForTimeout(150);const x=await p.evaluate(()=>{const r=s=>{const b=document.querySelector(s).getBoundingClientRect();return {left:b.left,top:b.top,bottom:b.bottom,width:b.width}};const i=document.querySelector('[data-dsg-allsky-image]');return {k:r('.dsg-status-kpi-grid'),d:r('[data-dsg-dome-sync]'),a:r('[data-dsg-allsky-live]'),i:r('[data-dsg-allsky-image]'),t:r('[data-dsg-allsky-live] .dsg-scene__toolbar'),fit:getComputedStyle(i).objectFit,overflow:document.documentElement.scrollWidth>innerWidth};});assert(!x.overflow,JSON.stringify(x));assert.equal(x.d.left,x.a.left);assert.equal(x.d.width,x.a.width);assert(x.a.top>x.d.bottom);assert.equal(x.fit,'contain');assert(x.i.bottom<=x.t.top,JSON.stringify(x));if(width>850){assert(Math.abs(x.k.top-x.d.top)<1,JSON.stringify(x));assert(Math.abs(x.k.bottom-x.a.bottom)<1,JSON.stringify(x));}}
await p.locator('[data-dsg-allsky-mode]').click();assert.equal(await p.locator('[data-dsg-allsky-live]').getAttribute('data-dsg-scene-state'),'essential');assert.equal(await p.locator('[data-dsg-scene-mode]').getAttribute('aria-pressed'),'true');console.log('PASS: aligned status panels at four widths, image containment and shared essential mode.');}finally{await b.close();}})().catch(e=>{console.error(e);process.exitCode=1;});
